import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _isLoadingMore = false;
  bool _hasMore = true;

  String _currentQuery = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadInitial();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // При возврате на экран (например, после переключения вкладки)
    // обновляем данные свежим запросом с базовой валютой проекта ('EUR').
    _resetAndReload();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitial() async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _currentPage = 0;
      _allCurrencies = [];
      _hasMore = true;
    });

    final page = await currencyRepository.fetchRates(const CurrencyPageRequest(base: 'EUR', page: 0));

    setState(() {
      _allCurrencies = List.from(page.items);
      _filteredCurrenciesNotifier = ValueNotifier(_allCurrencies);
      _currentPage = 1;
      _hasMore = page.hasMore;
      _isLoadingMore = false;
    });

    _fadeController.forward(); // запускаем анимацию
    currencyRepository.saveCurrencyList(page.items);
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() {
      _isLoadingMore = true;
    });

    final currencyRepository = context.read<CurrencyRepository>();
    final page = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'EUR', page: _currentPage));

    setState(() {
      if (page.hasMore) {
        _allCurrencies.addAll(page.items);
      } else {
        _hasMore = false;
      }
      _filteredCurrenciesNotifier.value = List.from(_allCurrencies);
      _currentPage++;
      _isLoadingMore = false;
    });

    currencyRepository.saveCurrencyList(page.items);
  }

  Future<void> _resetAndReload() async {
    final currencyRepository = context.read<CurrencyRepository>();

    setState(() {
      _currentPage = 0;
      _allCurrencies = [];
      _hasMore = true;
      _isLoadingMore = false;
    });

    final page = await currencyRepository.fetchRates(const CurrencyPageRequest(base: 'EUR', page: 0));

    setState(() {
      _allCurrencies = List.from(page.items);
      _filteredCurrenciesNotifier.value = _allCurrencies;
      _currentPage = 1;
      _hasMore = page.hasMore;
      _isLoadingMore = false;
    });

    currencyRepository.saveCurrencyList(_allCurrencies);
  }

  void _filterCurrencies(String query) {
    setState(() {
      _currentQuery = query.toLowerCase();
    });
    final String lowerQuery = _currentQuery;
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FadeTransition(
        opacity: _fadeController.view,
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
              child: SearchView(onChanged: _filterCurrencies),
            ),
            Expanded(
              child: ValueListenableBuilder<List<CurrencyModel>>(
                valueListenable: _filteredCurrenciesNotifier,
                builder: (BuildContext context, List<CurrencyModel> data, _) {
                  return NotificationListener<ScrollNotification>(
                    onNotification: (ScrollNotification notification) {
                      if (notification is ScrollEndNotification &&
                          _hasMore &&
                          !_isLoadingMore) {
                        final metrics = notification.metrics;
                        if (metrics.pixels >= metrics.maxScrollExtent) {
                          _loadMore();
                        }
                      }
                      return false;
                    },
                    child: ListView.builder(
                      itemCount: data.length + (_hasMore && !_isLoadingMore ? 0 : 1),
                      itemBuilder: (BuildContext context, int index) {
                        if (index >= data.length) {
                          // Показываем кнопку «Показать ещё» или индикатор загрузки
                          if (_isLoadingMore) {
                            return const Padding(
                              padding: EdgeInsets.all(16.0),
                              child: Center(child: CircularProgressIndicator()),
                            );
                          } else if (_hasMore) {
                            return Padding(
                              padding: const EdgeInsets.symmetric(vertical: 12.0),
                              child: SizedBox(
                                width: double.infinity,
                                child: ElevatedButton(
                                  onPressed: _loadMore,
                                  child: Text(context.loc.showMore),
                                ),
                              ),
                            );
                          } else {
                            return const SizedBox.shrink();
                          }
                        }

                        final CurrencyModel currency = data[index];

                        return Padding(
                          key: ValueKey(currency.id),
                          padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                          child: CurrencyCard(model: currency),
                        );
                      },
                      padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                    ),
                  );
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}
